  "explanations": [
    {
      "topic": {
        "text": "FizzBuzz program logic and common error",
        "refs": ["Q0003", "Q0004"]
      },
      "explanation_text": {
        "text": "When the first condition checks only divisibility by 5, numbers divisible by both 5 and 3 (e.g., 15) satisfy that condition and the subsequent else‑if clauses are skipped, resulting in only \"fizz\" being printed instead of \"fizzbuzz\".",
        "refs": ["Q0004"]
      },
      "explanation_type": null
    }
  ],
  "examples": [],
  "facts": [
    {
      "fact_text": {
        "text": "If a number is divisible by 5 (remainder zero when using the modulus operator), the program should print \"fizz\".",
        "refs": ["Q0002"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If a number is divisible by 3 (remainder zero when using the modulus operator), the program should print \"buzz\".",
        "refs": ["Q0003"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If a number is divisible by both 5 and 3, the program should print \"fizzbuzz\".",
        "refs": ["Q0001"]
      },
      "fact_type": null
    },
    {
      "fact_text": {
        "text": "If a number is not divisible by 5 or 3, the program should print the number itself.",
        "refs": ["Q0001"]
      },
      "fact_type": null
    }
  ],
  "formulas": [],
  "procedures": [
    {
      "procedure_name": {
        "text": "Read integer input and determine FizzBuzz output",
        "refs": ["Q0001"]
      },
      "steps": [
        {
          "text": "Import and instantiate a Scanner object to read from the terminal.",
          "refs": ["Q0001"]
        },
        {
          "text": "Prompt the user and read an integer into variable `number` using `scanner.nextInt()`.",
          "refs": ["Q0002"]
        },
        {
          "text": "Check if `number % 5 == 0`; if true, print \"fizz\".",
          "refs": ["Q0002"]
        },
        {
          "text": "Else if `number % 3 == 0`; if true, print \"buzz\".",
          "refs": ["Q0003"]
        },
        {
          "text": "Else if `number % 5 == 0 && number % 3 == 0`; if true, print \"fizzbuzz\".",
          "refs": ["Q0003"]
        },
        {
          "text": "Else print the number itself.",
          "refs": ["Q0003"]
        }
      ],
      "prerequisites": null,
      "outcomes": null,
      "content": {
        "text": "A simple console program that reads a number and prints \"fizz\", \"buzz\", \"fizzbuzz\", or the number based on divisibility rules.",
        "refs": ["Q0001"]
      }
    }
  ],
